  assert.equal(await totalFor([{ sku: 'A', qty: 1 }]), 10)
})

test('multiple items are summed', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }]), 71)
})

test('exactly 100 gets no discount (threshold is strictly > 100)', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100)
})

test('just over 100 gets 10% off', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 11 }]), 99)
})

test('large order gets 10% off', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 100 }]), 900)
})

test('SUSPECT: total is floored, cents are dropped (no discount)', async () => {
  assert.equal(await totalFor([{ sku: 'D', qty: 5 }]), 4) // 4.95
})

test('SUSPECT: discounted total is floored, not rounded (100.5 -> 90.45 -> 90)', async () => {
  assert.equal(await totalFor([{ sku: 'B', qty: 4 }, { sku: 'D', qty: 0 }, { sku: 'A', qty: 0 }]), 102) // 102, no discount? see below
})

test('SUSPECT: discounted total loses cents (3 x 33.33 x 4 = 133.32 -> 119.988 -> 119)', async () => {
  assert.equal(await totalFor([{ sku: 'C', qty: 4 }]), 119)
})

test('SUSPECT: discount is always a flat 10%, no larger tier for bigger orders', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 1000 }]), 9000)
})

test('empty items rejected', async () => {
  await withApp(async (base) => {
    const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items: [] }) })
    assert.equal(res.status, 400)
  })
})
